import numpy as np

def _dec(x, depth=0):
    while isinstance(x, str) and depth < 6:
        x = json.loads(x); depth += 1
    return x

def load_factor(f):
    d = _dec(json.loads(open(f).read()))
    if isinstance(d, list):
        d = d[0] if d else {}
    art = d.get("signal_artifact")
    if isinstance(art, str):
        art = _dec(art); d["signal_artifact"] = art
    return d

