# ---- collect all unique factors with artifacts ----
seen = {}
for f in sorted(glob.glob("factors/*.json")):
    if os.path.isdir(f): continue
    try:
        d = load_factor(f)
    except Exception:
        continue
    fid = d.get("factor_id")
    if not fid: continue
    art = d.get("signal_artifact") or {}
    has_art = bool(art.get("data_b64")) if isinstance(art, dict) else False
    cur = seen.get(fid)
    if cur is None:
        seen[fid] = (f, d, has_art)
    elif has_art and not cur[2]:
        seen[fid] = (f, d, has_art)

# reconstruct panels
panels = {}
for fid, (f, d, has_art) in seen.items():
    if not has_art: continue
    art = d["signal_artifact"]
    try:
        rawb = gzip.decompress(base64.b64decode(art["data_b64"]))
        M = np.frombuffer(rawb, dtype=np.float32).reshape(art["n_dates"], art["n_symbols"]).astype(float)
        panels[fid] = M
    except Exception as e:
        print("artifact fail", fid, repr(e)[:80])

