    print(f"  {fid:32s} shape={M.shape} nan={np.isnan(M).mean():.3f}")

# pairwise correlation on full window and last 252 rows
print("\nPairwise |corr| matrix (full window), threshold .7:")
def corr(a, b):
    m = np.isfinite(a) & np.isfinite(b)
    if m.sum() < 100: return np.nan
    if a[m].std()==0 or b[m].std()==0: return np.nan
    return float(np.corrcoef(a[m], b[m])[0,1])

n = len(fids)
